import React from 'react';
import {
    BrowserRouter as Router,
    Switch,
    Route,
    // Link
} from 'react-router-dom';
//pages
import PagesHome from './Home/Home';


const Root = () => {
    return (
        <Router>
            <Switch>
                <Route path="/" component={PagesHome} />
            </Switch>
        </Router>
    )
}

export default Root;