import './Banner.scss'
import React from 'react';

const Banner = ({imgDesk, imgMobile, text}) => {
    return(
        <>
        <section className="banner">
           <img className="banner__desk" src={imgDesk} alt={text} />
           <img className="banner__mobile" src={imgMobile} alt={text} />
        </section>
        </>
    )
}

export default Banner;