import './BannerRotate.scss'
import React from 'react';
//import $ from 'jquery';
import Slider from "react-slick";

//import de imagens
import banner1 from '../../images/banners/bannerHome.jpg'
import bannerMobile1 from '../../images/banners/bannerHomeMobile.jpg'
import banner2 from '../../images/banners/bannerTv.png'
import bannerMobile2 from '../../images/banners/bannerTvMobile.png'

const BannerRotate = () => {
    
    const settings = {
      dots: false,
      arrows: false,
      infinite: true,
      speed: 1000,
      slidesToShow: 1,
      slidesToScroll: 1,
      autoplaySpeed: 5000,
      autoplay: true
    };

    return (
        <>
        <div className="bannerRotate">
            <Slider  {...settings}>
                <div className="bannerRotate__box">
                    <a href="https://tv.asernet.com.br/login" target="_blank" rel="noreferrer"> <img src={banner2} alt="Banner Asernet" /> </a>
                </div>
                <div className="bannerRotate__box">
                    <img src={banner1} alt="Banner Asernet" />
                </div>
            </Slider>
        </div>
        <div className="bannerRotateMobile">
            <Slider  {...settings}>
                <div className="bannerRotate__box">
                <a href="https://tv.asernet.com.br/login" target="_blank" rel="noreferrer"> <img src={bannerMobile2} alt="Banner Asernet" /></a>
                </div>
                <div className="bannerRotate__box">
                    <img src={bannerMobile1} alt="Banner Asernet" />
                </div>
            </Slider>
        </div>
        </>
    );
  }


export default BannerRotate;

